import clsx from "clsx";

import "./entry-tree.css";

/**
 * @summary 엔트리 트리 컴포넌트 속성
 */
interface EntryTreeProps {
  /**
   * @field 트리에 표시할 엔트리 목록
   */
  entries: Array<{
    /**
     * @field 엔트리 식별자
     */
    id: string;
    /**
     * @field 엔트리 표시 이름
     */
    label: string;
  }>;
  /**
   * @field 선택된 엔트리 식별자
   */
  selectedId?: string;
}

export const EntryTree = ({entries, selectedId}: EntryTreeProps) => (
  <ul
    className={clsx(
      "rt_entriesEntryTree__list",
      selectedId && "rt_entriesEntryTree__list--selected",
    )}
  >
    {entries.map((entry) => (
      <li key={entry.id}>{entry.label}</li>
    ))}
  </ul>
);
